import{_ as a,o,c as r,a5 as e}from"./chunks/framework.BjM_ivYE.js";const u=JSON.parse('{"title":"계단 모드 정지","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/stair-mode-not-moving.md","filePath":"ko/manual/troubleshooting/stair-mode-not-moving.md","lastUpdated":1789720001000}'),n={name:"ko/manual/troubleshooting/stair-mode-not-moving.md"};function s(i,t,l,d,h,c){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="계단-모드-정지" tabindex="-1">계단 모드 정지 <a class="header-anchor" href="#계단-모드-정지" aria-label="Permalink to &quot;계단 모드 정지&quot;">​</a></h1><p>계단 모드에서 조이스틱을 밀어도 로봇이 앞으로 가지 않는 경우입니다. 가장 흔한 원인은 카메라 데이터를 정상적으로 받아오지 못하는 경우입니다.</p><h2 id="first-checks" tabindex="-1">먼저 확인할 것 <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;먼저 확인할 것 {#first-checks}&quot;">​</a></h2><ul><li>화면에서 현재 모드가 실제로 계단 모드로 바뀌었는지 확인합니다.</li><li><strong>L 스틱</strong>으로 조작하고 있는지 확인합니다.</li><li><strong>카메라 영상이 정상적으로 나오는지</strong> 확인합니다.</li></ul><h2 id="r-stick" tabindex="-1">R 스틱을 앞뒤로 밀어도 전진하지 않습니다 <a class="header-anchor" href="#r-stick" aria-label="Permalink to &quot;R 스틱을 앞뒤로 밀어도 전진하지 않습니다 {#r-stick}&quot;">​</a></h2><p><strong>원인:</strong> 계단 모드에서 전진·후진은 <strong>L 스틱</strong>이 맡습니다. 설계된 동작이며 고장이 아닙니다.</p><p><strong>해결:</strong> 아래와 같이 조작합니다.</p><table tabindex="0"><thead><tr><th>조작</th><th>동작</th></tr></thead><tbody><tr><td>L 스틱 전 · 후</td><td>전진 · 후진</td></tr><tr><td>L 스틱 좌 · 우</td><td>좌우 이동</td></tr><tr><td>R 스틱 좌 · 우</td><td>제자리 회전</td></tr></tbody></table><p>모드별 조작 방법은 <a href="/RBQ/ko/manual/gui/motion-commands.html">기본 동작 명령</a>에서 확인하세요.</p><h2 id="no-camera" tabindex="-1">카메라 영상이 나오지 않으면 움직이지 않습니다 <a class="header-anchor" href="#no-camera" aria-label="Permalink to &quot;카메라 영상이 나오지 않으면 움직이지 않습니다 {#no-camera}&quot;">​</a></h2><p><strong>원인:</strong> 계단 모드는 카메라 데이터를 기반으로 동작합니다. 카메라 영상이 나오지 않으면 조이스틱을 밀어도 로봇이 움직이지 않습니다.</p><p><strong>해결:</strong> 제어 홈 상단바의 로고 옆 상태 불빛을 탭해 <strong>시스템 종합 상태</strong>의 <code>비전</code> 행을 확인합니다. 영상이 나오지 않는다면 <a href="/RBQ/ko/manual/troubleshooting/no-camera-view.html">카메라 영상이 나오지 않을 때</a>의 절차를 먼저 진행하세요.</p><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p><strong><a href="/RBQ/ko/manual/gui/logs.html#real-time">로그 → Real Time</a></strong> 를 열어 계단 모드 버튼을 누른 시점의 메시지를 함께 알려주시면 확인이 빠릅니다.</p><p><strong>→ <a href="/RBQ/ko/manual/support/">기술지원 요청</a></strong></p>',15)])])}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
